  executionMode: IVXAutonomousCoderExecutionMode;
  approvalPolicy: 'owner_gated';
  ownerId: string;
  startingSha: string | null;
  filesInspected: string[];
  rootCause: string;
  technicalPlan: string;
  iterations: IVXAutonomousCoderIteration[];
