      changesRequired: typeof parsed.changesRequired === 'string' ? parsed.changesRequired : '',
      testsRequired: typeof parsed.testsRequired === 'string' ? parsed.testsRequired : '',
      risks: typeof parsed.risks === 'string' ? parsed.risks : '',
    };
  } catch {
    return null;
  }
}

